// מתרגם אירוע מה-CRM למייל. ליד חדש לא נשלח כאן: לידים מהאתר כבר מקבלים מייל מהתהליך של האתר.
const out = [];
const app = 'https://app.simple-solution.co.il';
const nis = (n) => Math.round(Number(n || 0)).toLocaleString('he-IL') + ' ₪';
for (const item of $input.all()) {
  const e = item.json.body || {};
  const d = e.data || {};
  const who = [d.name, d.biz].filter(Boolean).join(' · ') || 'לקוח';
  let subject = '', text = '';
  if (e.event === 'lead_returned') {
    subject = 'פנייה חוזרת: ' + who;
    text = who + ' השאיר/ה פרטים שוב.\nטלפון: ' + (d.phone || '-') + '\n\n' + app + '/leads/' + d.id;
  } else if (e.event === 'quote_viewed') {
    subject = 'הצעה ' + d.no + ' נפתחה';
    text = who + ' פתח/ה את הצעה ' + d.no + '.\nזה זמן טוב להתקשר.\nטלפון: ' + (d.phone || '-') + '\n\n' + app + '/quotes/' + d.id;
  } else if (e.event === 'quote_signed') {
    subject = 'הצעה ' + d.no + ' נחתמה';
    text = who + ' חתם/ה על הצעה ' + d.no + '.\nלחודש: ' + nis(d.totals && d.totals.monthly) + ' · חד פעמי: ' + nis(d.totals && d.totals.oneoff) + ' (לפני מע"מ)\n\nהלקוח, השירותים, התשלום ורשימת הקליטה כבר נפתחו במערכת.\n' + app + '/quotes/' + d.id;
  } else if (e.event === 'quote_rejected') {
    subject = 'הצעה ' + d.no + ' נדחתה';
    text = who + ' סימן/ה שההצעה לא מתאימה כרגע.\n\n' + app + '/quotes/' + d.id;
  } else continue;
  out.push({ json: { subject, text } });
}
return out;
